import { test, expect } from '@playwright/test';

test.describe('Dashboard Sidebar to Bottom Nav Bar Transition on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should transition sidebar to bottom nav bar on mobile view', async ({ page }) => {
    // Verify sidebar is visible on desktop
    const sidebar = page.getByRole('navigation', { name: /dashboard/i });
    await expect(sidebar).toBeVisible();

    // Verify sidebar contains expected links
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();

    const settingsLink = page.getByRole('link', { name: /settings/i });
    await expect(settingsLink).toBeVisible();

    const userLink = page.getByRole('link', { name: /user/i });
    await expect(userLink).toBeVisible();

    // Verify sidebar has correct initial state
    const sidebarState = page.getByRole('status', { name: /sidebar/i });
    await expect(sidebarState).toContainText('sidebar');

    // Navigate to mobile view
    await page.evaluate(() => {
      window.innerWidth = 375;
    });

    // Verify sidebar disappears and bottom nav appears
    const sidebar = page.getByRole('navigation', { name: /dashboard/i });
    await expect(sidebar).not.toBeVisible();

    const bottomNav = page.getByRole('navigation', { name: /bottom nav/i });
    await expect(bottomNav).toBeVisible();

    // Verify bottom nav contains expected links
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();

    const settingsLink = page.getByRole('link', { name: /settings/i });
    await expect(settingsLink).toBeVisible();

    const userLink = page.getByRole('link', { name: /user/i });
    await expect(userLink).toBeVisible();

    // Verify sidebar state is updated
    const sidebarState = page.getByRole('status', { name: /sidebar/i });
    await expect(sidebarState).toContainText('bottom nav');

    // Verify responsive design is applied
    const viewportWidth = page.evaluate(() => window.innerWidth);
    expect(viewportWidth).toBeLessThan(768);
  });

  test('should handle edge case where sidebar is already in bottom nav state', async ({ page }) => {
    // Navigate to mobile view
    await page.evaluate(() => {
      window.innerWidth = 375;
    });

    // Verify sidebar is already in bottom nav state
    const sidebar = page.getByRole('navigation', { name: /dashboard/i });
    await expect(sidebar).not.toBeVisible();

    const bottomNav = page.getByRole('navigation', { name: /bottom nav/i });
    await expect(bottomNav).toBeVisible();

    // Verify sidebar state is correct
    const sidebarState = page.getByRole('status', { name: /bottom nav/i });
    await expect(sidebarState).toContainText('bottom nav');

    // Verify links are still visible
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();

    const settingsLink = page.getByRole('link', { name: /settings/i });
    await expect(settingsLink).toBeVisible();

    const userLink = page.getByRole('link', { name: /user/i });
    await expect(userLink).toBeVisible();

    // Verify responsive design is still applied
    const viewportWidth = page.evaluate(() => window.innerWidth);
    expect(viewportWidth).toBeLessThan(768);
  });
});
